import{_ as e,c as a,o as i,ag as l}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Evolutionarily-stable-strategy","description":"","frontmatter":{"title":"Evolutionarily-stable-strategy"},"headers":[],"relativePath":"general/evolutionarily-stable-strategy.md","filePath":"general/evolutionarily-stable-strategy.md","lastUpdated":null}'),o={name:"general/evolutionarily-stable-strategy.md"};function r(s,t,n,c,y,u){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="evolutionarily-stable-strategy" tabindex="-1">Evolutionarily-stable-strategy <a class="header-anchor" href="#evolutionarily-stable-strategy" aria-label="Permalink to &quot;Evolutionarily-stable-strategy&quot;">​</a></h1><h2 id="evolutionarily-stable-strategy-1" tabindex="-1">Evolutionarily Stable Strategy <a class="header-anchor" href="#evolutionarily-stable-strategy-1" aria-label="Permalink to &quot;Evolutionarily Stable Strategy&quot;">​</a></h2><p>A theoretical analysis is made of the evolution of behavioral strategies in contest situations. It is assumed that behavior will evolve so as to maximize individual fitness. If so, a population will evolve an ‘evolutionarily stable strategy’, or ESS, which can be defined as a strategy such that, if all members of a population adopt it, no ‘mutant’ strategy can do better. <a href="https://www.sciencedirect.com/science/article/abs/pii/S0003347276801108" target="_blank" rel="noreferrer">https://www.sciencedirect.com/science/article/abs/pii/S0003347276801108</a></p><p>I’m rereading The Selfish Gene again to try to understand my thoughts on the stability of environments from a few years ago.</p>',4)])])}const b=e(o,[["render",r]]);export{h as __pageData,b as default};
